using Microsoft.CodeAnalysis.Testing;
using VerifyCS = CSharpSourceGeneratorVerifier<MessagePack.SourceGenerator.MessagePackGenerator>;

namespace Receipts.GeneratedTests;

public class SuppressedSourceGenerationAnalyzerTests
{
    private static async Task RunAsync(string source)
    {
        var test = new VerifyCS.Test
        {
            TestBehaviors = TestBehaviors.SkipGeneratedSourcesCheck,
        };
        test.TestState.Sources.Add(source);
        await test.RunAsync();
    }

    [Fact]
    public async Task MissingKey_OnSuppressedType_ReportsMsgPack004()
    {
        string source = """
            using MessagePack;

            [MessagePackObject(SuppressSourceGeneration = true)]
            public class MyObject
            {
                [Key(0)]
                public int A;

                public int {|MsgPack004:B|};
            }
            """;
        await RunAsync(source);
    }

    [Fact]
    public async Task DuplicateIntKeys_OnSuppressedType_ReportsMsgPack005()
    {
        string source = """
            using MessagePack;

            [MessagePackObject(SuppressSourceGeneration = true)]
            public class MyObject
            {
                [Key(0)]
                public int A;

                [Key(0)]
                public int {|MsgPack005:B|};
            }
            """;
        await RunAsync(source);
    }

    [Fact]
    public async Task MixedKeys_OnSuppressedType_ReportsMsgPack005()
    {
        string source = """
            using MessagePack;

            [MessagePackObject(SuppressSourceGeneration = true)]
            public class MyObject
            {
                [Key(0)]
                public int A;

                [Key("b")]
                public int {|MsgPack005:B|};
            }
            """;
        await RunAsync(source);
    }
}
